    statistics_root='data/decision_executable_profit/forward/statistics/'
    summary_relative=statistics_root+'summary.json'

    def read_exact(relative):
        path=root/relative
        if (
            Path(relative).is_absolute() or '..' in Path(relative).parts
            or not path.is_file() or path.is_symlink()
            or not path.resolve(strict=True).is_relative_to(root)
        ):
            raise ValueError(f'Shadow candidate source is unsafe: {relative}')
        return path.read_bytes()

    index_relative='outputs/decision/executable_profit_research/shadow_index.json'
