    snapshot_sha=str(index.get('latest_state_snapshot_sha256') or '')
    legacy_state=public_root+f'shadow_state_{d}_asof_{d}.json'
    versioned=state_relative != legacy_state
    expected_state=(
        public_root+f'shadow_state_{d}_asof_{d}_sha256_{snapshot_sha}.json'
        if versioned else legacy_state
    )
    if re.fullmatch(r'[0-9a-f]{64}',snapshot_sha) is None or state_relative != expected_state:
        raise ValueError('Shadow candidate state address is not exact')
    state_bytes=read_exact(state_relative)
    state=json.loads(state_bytes)
    binding=state['source_bindings']['statistics']
    statistics_sha=str(binding.get('sha256') or '')
    statistics_relative=(
        statistics_root+f'snapshots/summary_asof_{d}_sha256_{statistics_sha}.json'
        if versioned else summary_relative
    )
    if (
        re.fullmatch(r'[0-9a-f]{64}',statistics_sha) is None
        or binding.get('path') != statistics_relative
        or hashlib.sha256(state_bytes).hexdigest() != index.get('latest_state_sha256')
        or state.get('snapshot_sha256') != snapshot_sha
        or state.get('signal_date') != d or state.get('as_of_date') != d
        or binding.get('as_of_date') != d
        or index.get('latest_signal_date') != d or index.get('latest_as_of_date') != d
    ):
