    for key,relative in (
        ('public_index',index_relative),('public_state',state_relative),
        ('statistics',statistics_relative),
    ):
        if Path(chain[key]).resolve(strict=True) != (root/relative).resolve(strict=True):
            raise ValueError('Shadow candidate differs from validated repository chain')
    statistics_bytes=read_exact(statistics_relative)
    if (
        hashlib.sha256(statistics_bytes).hexdigest() != statistics_sha
        or read_exact(summary_relative) != statistics_bytes
    ):
        raise ValueError('Shadow candidate summary/snapshot bytes drifted')
    required={
        f'data/decision_executable_profit/forward/selections/shadow_{d}.json',
        f'data/decision_executable_profit/forward/selections/shadow_{d}.csv',
        'data/decision_executable_profit/forward/selections/primary_mixed_index.json',
        summary_relative,statistics_relative,state_relative,index_relative,
    }
    expected=set(required)
    if previous_statistics is not None and versioned:
        previous=previous_statistics
        previous_date=str(previous.get('as_of_date') or '')
        previous_sha=str(previous.get('sha256') or '')
        archive=(statistics_root+'snapshots/'
                 f'summary_asof_{previous_date}_sha256_{previous_sha}.json')
        if (
            set(previous) != {'as_of_date','sha256','path','existed'}
            or re.fullmatch(r'20[0-9]{6}',previous_date) is None or previous_date > d
            or re.fullmatch(r'[0-9a-f]{64}',previous_sha) is None
            or previous.get('path') != archive or type(previous.get('existed')) is not bool
            or hashlib.sha256(read_exact(archive)).hexdigest() != previous_sha
        ):
            raise ValueError('Shadow candidate previous-summary archive drifted')
        expected.add(archive)
        if not previous['existed']:
            required.add(archive)
    return expected,required

